WITH combined AS ( SELECT 'REFUNDED' AS role, cr.cr_refunded_hdemo_sk AS hd_demo_sk, cr.cr_return_quantity, cr.cr_net_loss FROM catalog_returns cr UNION ALL SELECT 'RETURNING' AS role, cr.cr_returning_hdemo_sk, cr.cr_return_quantity, cr.cr_net_loss FROM catalog_returns cr ) SELECT role, hd.hd_demo_sk, hd.hd_income_band_sk, hd.hd_buy_potential, SUM(combined.cr_return_quantity) AS total_return_qty, SUM(combined.cr_net_loss) AS total_net_loss, COUNT(*) AS return_records, MAX(combined.cr_return_quantity) AS max_return_qty, MIN(combined.cr_return_quantity) AS min_return_qty FROM combined JOIN household_demographics hd ON combined.hd_demo_sk = hd.hd_demo_sk WHERE combined.cr_net_loss <> 0 GROUP BY role, hd.hd_demo_sk, hd.hd_income_band_sk, hd.hd_buy_potential ORDER BY total_net_loss DESC
